mapper.select:
SELECT g.id, g.type_id, g.confidence, g.latitude, g.longitude, g.timestamp, g.image_url, g.processed_image_url, g.create_time,
       gt.name as type_name, gt.description as type_description
FROM garbage_data g
LEFT JOIN garbage_types gt ON g.type_id = gt.id
WHERE 1=1

    AND g.type_id = #{typeId}


    AND g.timestamp >= #{startTime}


    AND g.timestamp <= #{endTime}


    AND g.latitude BETWEEN #{minLatitude} AND #{maxLatitude}
    AND g.longitude BETWEEN #{minLongitude} AND #{maxLongitude}

ORDER BY g.timestamp DESC

    LIMIT #{pageSize} OFFSET #{offset}

