SELECT gt.name as typeName, COUNT(*) as count FROM garbage_data g LEFT JOIN garbage_types gt ON g.type_id = gt.id
g.timestamp BETWEEN #{startTime} AND #{endTime}
GROUP BY g.type_id, gt.name ORDER BY count DESC

SELECT DATE_FORMAT(g.timestamp, '%Y-%m-%d') as date, COUNT(*) as count FROM garbage_data g
g.timestamp BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE_FORMAT(g.timestamp, '%Y-%m-%d') ORDER BY date

SELECT COUNT(*)
FROM garbage_data g
WHERE 1=1

    AND g.type_id = #{typeId}


